-- Allow query history for SigNoz metrics queries (metrics_query_signoz). Extends the
-- allowlist without scanning legacy rows, like V935.
alter table "public"."user_history" drop constraint if exists "module_check";
alter table "public"."user_history" add constraint "module_check" check (module = ANY (ARRAY['log_query_loki'::text, 'log_query_signoz'::text, 'log_query_datadog'::text, 'log_query_observe'::text, 'log_query_loggly'::text, 'log_query_azure_app_insights'::text, 'log_query_aws_cloudwatch'::text, 'log_query_es'::text, 'log_query_newrelic'::text, 'log_query_splunk_observability_platform'::text, 'log_query_dynatrace'::text, 'log_query_solarwinds'::text, 'log_query_pinot'::text, 'log_query_hive'::text, 'metrics_query_prometheus'::text, 'metrics_query_datadog'::text, 'metrics_query_chronosphere'::text, 'metrics_query_aws_cloudwatch'::text, 'metrics_query_azure_app_insights'::text, 'metrics_query_newrelic'::text, 'metrics_query_splunk_observability_platform'::text, 'metrics_query_es'::text, 'metrics_query_dynatrace'::text, 'metrics_query_solarwinds'::text, 'metrics_query_victoria-metrics'::text, 'metrics_query_victoria_metrics'::text,'log_query_cubeapm'::text,'log_query_splunk_enterprise'::text,'metrics_query_cubeapm'::text,'metrics_query_splunk_enterprise'::text,'metrics_query_signoz'::text])) not valid;
